-- Import the first flattened source as 30 individually selectable Lily facts.
-- Section headings and line breaks were lost in transit, so headings are
-- removed and only sentence-boundary-separated facts are preserved.
WITH supplied_facts (ordinal, text) AS (
VALUES
  (779, $$Слово «Агония»: Происходит от древнегреческого Agon — «борьба», «состязание атлетов». В литературе Нового времени термин перешел из спортивного контекста в медицинский, означая финальную предсмертную борьбу организма за жизнь.$$),
  (780, $$Происхождение слова «Саркофаг»: Буквально с греческого переводится как «пожиратель мяса». Античный писатель Плиний Старший объяснял, что первые саркофаги делались из известняка, добываемого в Ассосе, который якобы обладал свойством растворять тела умерших за 40 дней.$$),
  (781, $$Слово «Плутократия»: Введено в оборот греческим комедиографом Аристофаном в его последней пьесе «Плутос», где бог богатства Плутос изображен слепым, из-за чего деньги достаются только подлецам, превращая власть в правление богатых дураков.$$),
  (782, $$Слово «Меланхолия»: Буквально переводится с греческого как «черная желчь» (Melaina chole). В медицинских и философских трактатах Аристотеля считалось, что избыток этой жидкости в организме рождает гениев, поэтов и безумцев.$$),
  (783, $$Термин «Плагиат»: Впервые юридически и литературно зафиксирован в эпиграммах Марциала, который сравнил кражу своих стихов с plagium — похищением свободных детей с целью продажи их в рабство.$$),
  (784, $$Слово «Лабиринт»: Изначально в античной литературе (у Геродота) означало не просто запутанные коридоры, а дворец с множеством залов. Лингвисты доказали, что корень слова восходит к лидийскому Labrys — двухсторонний боевой топор, который был священным символом минойской культуры.$$),
  (785, $$Происхождение слова «Шедевр»: Латинский парафраз Magnum opus («Великая работа»), используемый античными риторами для обозначения главного, итогового труда жизни писателя или художника.$$),
  (786, $$Слово «Стигма»: В древнегреческой литературе так называли клеймо, которое выжигали на теле беглых рабов или преступников. Сегодня термин официально используется в социологии и психиатрии для обозначения социального клеймения.$$),
  (787, $$Термин «Эпилог»: Происходит от греческого Epilogos — «послесловие». В античной трагедии это была финальная речь актера, подводившая итог и объяснявшая зрителю мораль пьесы.$$),
  (788, $$Слово «Парадокс»: Буквально переводится с латыни и греческого как «противное общему мнению» (Para doxa). Цицерон ввел этот термин в римскую философию в книге «Парадоксы стоиков», чтобы описать утверждения, кажущиеся абсурдными обывателям, но логически верные для мудрецов.$$),
  (789, $$Утерянная библиотека Филодема: При раскопках виллы в Геркулануме ученые нашли тысячи обугленных свитков. Долгое время их считали просто кусками угля и выбрасывали. Только в XX веке выяснилось, что это уникальная библиотека эпикурейского философа и поэта Филодема Гадарского, чьи тексты мир читает сегодня с помощью рентгена.$$),
  (790, $$«История Рима» Ливия: Из 142 книг монументального труда Ливия до нас дошло только 35. Остальные книги известны лишь по кратким средневековым пересказам (периохам). Поиск утерянных свитков Ливия был главным хобби ученых эпохи Возрождения.$$),
  (791, $$Защита от сырости свитков: Римский агроном Колумелла в трактате «О сельском хозяйстве» давал инструкции по строительству домашних библиотек: окна должны были выходить строго на восток, чтобы утреннее солнце просушивало папирусы, а северных окон следовало избегать из-за влажности, губящей чернила.$$),
  (792, $$Первые аудиокниги древности: Римские патриции (например, Плиний Младший) редко читали сами. У них были специальные рабы-чтецы (лекторы), которые читали им свитки вслух во время обеда, прогулок в паланкинах или перед сном, что является полным аналогом современного прослушивания аудиокниг.$$),
  (793, $$Секретные чернила античности: Овидий в поэме «Наука любви» давал женщинам практический совет, как писать тайные любовные письма, чтобы муж не заметил: нужно писать свежим молоком. Когда жидкость высыхает, она становится невидимой, но если посыпать лист угольной пылью, буквы четко проявляются.$$),
  (794, $$«Аттические ночи» Авла Геллия: Этот 20-томный труд II века н.э. — прообраз современных интеллектуальных блогов. Автор собирал воедино обрывки бесед, филологические споры, странные законы и забавные анекдоты, которые он услышал от друзей во время зимних вечеров в Аттике.$$),
  (795, $$Первый закон об авторском праве: В Александрии во время поэтических состязаний филолог Аристофан Византийский уличил нескольких поэтов в плагиате. Он по памяти указал свитки в библиотеке, откуда были украдены строки. Плагиаторов с позором изгнали, а Птолемей издал указ, запрещающий выдавать чужие стихи за свои под угрозой штрафа.$$),
  (796, $$Появление курсива: Переход от строгого квадратного капитального письма к быстрому курсиву (письму на бегу) произошел в Риме из-за развития бюрократии и переписки. Чиновники империи не имели времени выводить каждую букву, что навсегда изменило начертание латинского алфавита.$$),
  (797, $$Утерянные трагедии Черного цвета: Из 90 пьес Эсхила до нас дошло только 7. Главной причиной гибели рукописей стала их плохая копируемость в Византии: монахи предпочитали переписывать религиозные тексты, а языческие драмы оставляли гнить в подвалах.$$),
  (798, $$«Сатирикон» Петрония как пазл: Великий римский роман дошел до нас в виде разрозненных обрывков и цитат, сохраненных средневековыми грамматиками. Самый большой кусок — «Пир Трималхиона» — был случайно найден в хорватском городе Трогир только в XVII веке.$$),
  (799, $$Метафора «Любовный напиток»: Образ зелья, вызывающего безумную страсть (прообраз любовных эликсиров в фэнтези), детально описан в поэме Лукреция «О природе вещей», где автор предупреждает, что слепая страсть — это химическое отравление мозга, лишающее человека разума.$$),
  (800, $$«Лекарство от любви» Овидия: Эта поэма — первый в истории учебник по психотерапии расставания. Овидий дает практические советы, как пережить несчастную любовь: загрузить себя работой, уехать в деревню, сжечь письма бывшей и никогда не общаться с её подругами.$$),
  (801, $$Образ верного напарника (Ахилл и Патрокл): Гомер создал канон трагической связи по оружию: гибель Патрокла заставляет Ахилла забыть о личных обидах и вернуться в бой ради мести, что является базовым сценарным кодом для всех современных боевиков.$$),
  (802, $$Первая психологическая повесть: «Дафнис и Хлоя» Лонга — это детальное описание зарождения чувства у подростков, которые не имеют сексуального опыта и принимают любовь за тяжелую физическую болезнь, страдая от незнания анатомии и эмоций.$$),
  (803, $$Амбивалентность чувств Катулла: Его знаменитое двустишие «Odi et amo» («Ненавижу и люблю») заложило основу всей психологической лирики Европы, доказав, что человеческое сердце способно одновременно испытывать противоположные эмоции к одному объекту.$$),
  (804, $$Миф об Андрогинах: Концепция Платона из трактата «Пир» о том, что люди изначально были разрезаны богами пополам, и теперь каждый ищет свою «вторую половинку», до сих пор является главным романтическим мифом массовой культуры.$$),
  (805, $$Жанр Погребального плача (Эпитафия): Традиция писать поэтические надгробия с кратким изложением достоинств ушедшего человека была доведена до совершенства в стихотворениях Марциала на смерть маленькой рабыни Эротион, что изменило мемориальную культуру Европы.$$),
  (806, $$Образ Купидона с повязкой на глазах: Концепция того, что любовь слепа, зафиксирована в поздней римской литературе Александрийской школы, где Амура начали изображать с завязанными глазами, подчеркивая хаотичность и несправедливость его выбора.$$),
  (807, $$Образ преданной жены (Алinitial): Трагедия Еврипида «Алькеста» (Альцеста), где жена добровольно соглашается умереть вместо своего мужа Адмета, закрепила в литературе эталон жертвенной любви, который эксплуатировался викторианской прозой.$$),
  (808, $$Поэзия повседневности: Римский лирик Гораций первым доказал, что объектом высокой поэзии может быть не только битва героев, но и описание старой дубовой бочки с вином, скрип телеги на горной дороге или прохлада источника Бандузия в жаркий день.$$)
)
INSERT INTO "philology_facts" ("id", "text", "category", "characterEmotion", "updatedAt")
SELECT
  'lily-library-' || lpad(ordinal::text, 5, '0'),
  text,
  'LITERATURE',
  CASE ordinal % 3 WHEN 1 THEN 'THOUGHTFUL' WHEN 2 THEN 'SURPRISED' ELSE 'JOYFUL' END,
  CURRENT_TIMESTAMP
FROM supplied_facts;

-- Keep the existing editorial pause for Russia-, Russian-, USSR-, and
-- Soviet-related cards reversible: records remain stored but not delivered.
UPDATE "philology_facts"
SET "isActive" = FALSE, "updatedAt" = CURRENT_TIMESTAMP
WHERE "isActive" = TRUE
  AND "text" ~* '(росси|русск|ссср|советск|большевик|петроград|кремл|сталин|пастернак|достоевск|толст|пушкин|гогол|лермонтов|чехов|есенин|маяковск|тургенев|некрасов|гумилев|ахматов|мандельштам|зощенко|салтыков|жуковск|грибоедов|булгаков|бунин|куприн|горьк|фет|фонвизин|тютчев|жданов|солженицын|стругацк|ильф|петров|набоков|чуковск|крылов|беляев|акунин|гайдар|блок|волошин|бендер|ппш|живаго|облонск|мюнхгаузен)';
